from cardio_1 import a, G
from cardio_2 import t
# J47 — Bronchiectasies (P-02-Pneumologie). Abréviations nouvelles du cours, définition littérale lettre à lettre.
a('BSI',[('B','Bronchiectasis'),('S','Severity'),('I','Index')],'Bronchiectasis Severity Index (indice de sévérité des bronchiectasies)','<p>Score pronostique à neuf variables (âge, indice de masse corporelle, VEMS, hospitalisation dans les deux ans, exacerbations, dyspnée, colonisation, <i>Pseudomonas aeruginosa</i>, extension radiologique), de 0 à 26 points : 0 à 4 léger, 5 à 8 modéré, 9 ou plus sévère (Chalmers, 2014).</p>','j47-bsi')
a('FACED',[('F','FEV1 (VEMS)'),('A','Age (âge)'),('C','Chronic colonisation (colonisation chronique à Pseudomonas aeruginosa)'),('E','Extension (nombre de lobes atteints)'),('D','Dyspnoea (dyspnée)')],'Score FACED','<p>Score pronostique de mortalité à cinq ans, de 0 à 7 points : 0 à 2 léger, 3 à 4 modéré, 5 à 7 sévère (Martínez-García, 2014).</p>','j47-faced')
a('E-FACED',[('E','Exacerbations (avec hospitalisation dans l’année précédente)'),('FACED','score FACED')],'Score E-FACED','<p>Score FACED auquel s’ajoutent 2 points pour au moins une exacerbation hospitalisée dans l’année précédente ; total de 0 à 9 points (Martínez-García, 2017).</p>','j47-faced')
a('MRC',[('M','Medical'),('R','Research'),('C','Council')],'Medical Research Council (échelle de dyspnée du)','<p>Échelle britannique de dyspnée d’effort en cinq grades ; le BSI emploie la version de 1 à 5, le score FACED une version de 0 à IV.</p>')
a('MNT',[('M','Mycobactéries'),('N','Non'),('T','Tuberculeuses')],'Mycobactéries non tuberculeuses','<p>Mycobactéries de l’environnement (sol, eau, réseaux d’eau chaude), surtout du complexe <i>Mycobacterium avium</i> et <i>Mycobacterium abscessus</i> ; elles colonisent ou infectent les bronches dilatées.</p>','j47-mnt')
a('DCP',[('D','Dyskinésie'),('C','Ciliaire'),('P','Primitive')],'Dyskinésie ciliaire primitive','<p>Maladie génétique, le plus souvent autosomique récessive, des cils mobiles : clairance mucociliaire défaillante, rhinosinusite chronique, otites, infertilité, situs inversus dans environ la moitié des cas.</p>','j47-dcp')
a('CFTR',[('C','Cystic'),('F','Fibrosis'),('T','Transmembrane conductance'),('R','Regulator')],'Régulateur de la conductance transmembranaire de la mucoviscidose','<p>Canal épithélial du chlorure et du bicarbonate, codé par le gène du même nom ; ses variants pathogènes bialléliques causent la mucoviscidose (E84).</p>','j47-cf')
a('F508del',[('F','phénylalanine (code à une lettre F)'),('508','position 508 de la protéine'),('del','délétion')],'Variant F508del du gène CFTR','<p>Délétion de la phénylalanine en position 508 de la protéine CFTR ; variant pathogène le plus fréquent de la mucoviscidose en Europe.</p>','j47-cf')
a('DPP-1',[('D','Dipeptidyl'),('P','Peptidase'),('1','de type 1')],'Dipeptidyl peptidase 1 (cathepsine C)','<p>Enzyme des promyélocytes de la moelle osseuse qui active les sérine-protéases des neutrophiles (élastase, protéinase 3, cathepsine G) ; cible du brensocatib.</p>','j47-d-dpp1')
a('DICV',[('D','Déficit'),('I','Immunitaire'),('C','Commun'),('V','Variable')],'Déficit immunitaire commun variable','<p>Déficit primitif de la production d’anticorps : IgG basses, IgA et/ou IgM basses, réponse vaccinale altérée ; infections bactériennes respiratoires récidivantes et bronchiectasies.</p>','j47-dici')
a('BAAR',[('B','Bacilles'),('A','Acido-'),('A','Alcoolo-'),('R','Résistants')],'Bacilles acido-alcoolo-résistants','<p>Bacilles qui retiennent la fuchsine après décoloration par l’acide et l’alcool (coloration de Ziehl-Neelsen) : mycobactéries tuberculeuses et non tuberculeuses.</p>','j47-mnt')
a('Ziehl-Neelsen',[('Ziehl','Franz Ziehl, bactériologiste'),('Neelsen','Friedrich Neelsen, pathologiste')],'Coloration de Ziehl-Neelsen','<p>Coloration à chaud par la fuchsine phéniquée qui révèle les bacilles acido-alcoolo-résistants.</p>','j47-mnt')
a('EMBARC',[('E','European'),('M','Multicentre'),('B','Bronchiectasis'),('A','Audit and'),('R','Research'),('C','Collaboration')],'European Multicentre Bronchiectasis Audit and Research Collaboration','<p>Réseau et registre européens des bronchiectasies, source principale des données cliniques européennes.</p>')
a('ISHAM',[('I','International'),('S','Society for'),('H','Human and'),('A','Animal'),('M','Mycology')],'International Society for Human and Animal Mycology','<p>Société internationale de mycologie ; son groupe de travail a révisé en 2024 les critères de l’aspergillose bronchopulmonaire allergique.</p>','j47-abpa')
a('BTS',[('B','British'),('T','Thoracic'),('S','Society')],'British Thoracic Society (Société thoracique britannique)','<p>Société savante britannique ; recommandation sur les bronchiectasies de l’adulte (2019) et sur les macrolides au long cours (2020).</p>')
a('GRADE',[('G','Grading of'),('R','Recommendations,'),('A','Assessment,'),('D','Development and'),('E','Evaluation')],'Méthode GRADE','<p>Méthode de cotation de la certitude des preuves (élevée, modérée, faible, très faible) et de la force des recommandations (forte ou conditionnelle).</p>')
a('ROSE',[('R','Radiology (bronchiectasies à la tomodensitométrie)'),('O','Obstruction (VEMS/CVF &lt; 0,70)'),('S','Symptoms (symptômes)'),('E','Exposure (tabac ≥ 10 paquets-années ou autre exposition)')],'Critères ROSE de l’association bronchiectasies et BPCO','<p>Critères proposés pour reconnaître une BPCO chez un patient porteur de bronchiectasies : quatre éléments réunis.</p>','j47-bpco')
a('Q33.4',[('Q33','malformation congénitale du poumon'),('.4','bronchiectasie congénitale')],'CIM-10-GM Q33.4 — Bronchiectasie congénitale','<p>Exclue de la catégorie J47.</p>')
a('Williams-Campbell',[('Williams','Howard Williams, pédiatre australien'),('Campbell','Peter Campbell, pédiatre australien')],'Syndrome de Williams-Campbell','<p>Déficit congénital du cartilage des bronches de 4e à 6e génération, responsable de bronchiectasies proximales.</p>','j47-rare')
a('Mounier-Kuhn',[('Mounier','Pierre Mounier, oto-rhino-laryngologiste'),('Kuhn','Kuhn, coauteur de la description de 1932')],'Syndrome de Mounier-Kuhn (trachéobronchomégalie)','<p>Dilatation congénitale de la trachée et des bronches principales par atrophie des fibres élastiques et musculaires ; rétention des sécrétions et bronchiectasies.</p>','j47-rare')
a('DNAH5',[('DNA','Dynein, Axonemal'),('H','Heavy chain'),('5','numéro 5')],'Gène DNAH5 (chaîne lourde 5 de la dynéine axonémale)','<p>Gène le plus souvent muté dans la dyskinésie ciliaire primitive ; ses variants suppriment les bras externes de dynéine.</p>','j47-dcp')
a('DNAI1',[('DNA','Dynein, Axonemal'),('I','Intermediate chain'),('1','numéro 1')],'Gène DNAI1 (chaîne intermédiaire 1 de la dynéine axonémale)','<p>Gène de la dyskinésie ciliaire primitive avec absence des bras externes de dynéine.</p>','j47-dcp')
a('MUC5B',[('MUC','MUCine'),('5B','5B')],'Mucine MUC5B','<p>Mucine sécrétée par les glandes sous-muqueuses ; principale mucine du mucus normal des voies aériennes.</p>')
a('MUC5AC',[('MUC','MUCine'),('5AC','5AC')],'Mucine MUC5AC','<p>Mucine des cellules caliciformes ; augmentée dans le mucus des bronchiectasies et de l’asthme.</p>')
t('EMBRACE',[('EMBRACE','nom d’essai « Effectiveness of Macrolides in patients with BRonchiectasis using Azithromycin to Control Exacerbations », non strictement lettre à lettre')],'Essai EMBRACE (2012)','<p>Azithromycine 500 mg trois fois par semaine pendant six mois contre placebo chez 141 adultes néo-zélandais : moins d’exacerbations.</p>','j47-d-azi')
t('BAT',[('B','Bronchiectasis'),('A','and long-term Azithromycin'),('T','Treatment')],'Essai BAT (2013)','<p>Azithromycine 250 mg par jour pendant douze mois contre placebo chez 83 adultes néerlandais ayant au moins trois infections traitées dans l’année : moins d’exacerbations.</p>','j47-d-azi')
t('BLESS',[('B','Bronchiectasis and'),('L','Low-dose'),('E','Erythromycin'),('S','Study'),('S','(second S du sigle)')],'Essai BLESS (2013)','<p>Érythromycine éthylsuccinate 400 mg deux fois par jour pendant 48 semaines : moins d’exacerbations, au prix d’une sélection de streptocoques oropharyngés résistants aux macrolides.</p>','j47-d-ery')
t('ASPEN',[('ASPEN','nom d’essai de phase 3 du brensocatib, sans développement lettre à lettre publié dans l’article principal')],'Essai ASPEN (2025)','<p>Brensocatib 10 mg ou 25 mg une fois par jour contre placebo chez 1 721 patients : taux annualisé d’exacerbations réduit d’environ 20 %.</p>','j47-d-dpp1')
t('PROMIS',[('PROMIS','nom d’essai (« PROMIS I et II »), sans développement lettre à lettre publié dans l’article principal')],'Essais PROMIS I et II (2024)','<p>Colistiméthate sodique inhalé deux fois par jour contre placebo chez des patients infectés par <i>Pseudomonas aeruginosa</i> : bénéfice dans PROMIS I, non reproduit dans PROMIS II interrompu par la pandémie.</p>','j47-d-inh')
a('Royaume-Uni',[('Royaume','Royaume'),('Uni','-Uni')],'Royaume-Uni de Grande-Bretagne et d’Irlande du Nord','<p>Nom de pays, et non abréviation ; enregistré pour l’affichage cohérent des noms composés.</p>')
a('Martínez-García',[('Martínez','Miguel Ángel Martínez'),('García','-García, pneumologue espagnol')],'Martínez-García M. A.','<p>Auteur principal des scores FACED (2014) et E-FACED (2017).</p>','j47-faced')
a('McCullough',[('Mc','préfixe patronymique écossais et irlandais'),('Cullough','Cullough')],'McCullough B.','<p>Auteur principal de la méta-analyse de 2026 sur les agents mucoactifs dans les bronchiectasies (European Respiratory Review).</p>','j47-d-sshyp')
a('McKelvey',[('Mc','préfixe patronymique écossais et irlandais'),('Kelvey','Kelvey')],'McKelvey M. C.','<p>Auteur principal de la sous-étude mécanistique de 2026 sur la rhéologie des crachats sous agents mucoactifs.</p>','j47-d-muco')
